#include "../src/offline_weather.hpp"
#include <cassert>
#include <iostream>
using namespace day;
int main(){Weather w;w.valid=true;w.temperature=99;w.code=0;w.time="2026-10-07T10:00";w.dates={"2026-10-07","2026-10-08"};w.lows={3,5};w.highs={13,15};w.details={{"daily",{{"weather_code",{3,61}}}},{"hourly",{{"time",{"2026-10-07T10:00","2026-10-08T00:00","2026-10-08T10:00"}},{"temperature_2m",{8,6,11}},{"weather_code",{3,61,2}}}}};auto first=weatherNow(w,{2026,10,7},10,false);assert(first.valid&&first.forecast&&first.hourly&&first.temperature==8&&first.code==3);auto second=weatherNow(w,{2026,10,8},10,false);assert(second.temperature==11&&second.code==2&&second.low==5&&second.high==15&&second.day==1);auto midnight=weatherNow(w,{2026,10,8},0,false);assert(midnight.temperature==6&&midnight.code==61);auto observed=weatherNow(w,{2026,10,7},10,true);assert(!observed.forecast&&observed.temperature==99);auto later=weatherNow(w,{2026,10,8},10,true);assert(later.forecast&&later.temperature==11);auto daily=weatherNow(w,{2026,10,8},20,false);assert(daily.valid&&!daily.hourly&&std::isnan(daily.temperature)&&daily.low==5&&daily.high==15&&daily.code==61);assert(!weatherNow(w,{2026,10,9},10,false).valid);assert(!weatherNow(w,{2026,10,6},10,false).valid);w.details["hourly"]["temperature_2m"][1]=nullptr;auto missing=weatherNow(w,{2026,10,8},0,false);assert(missing.valid&&!missing.hourly);w.time="2026-10-07";assert(weatherNow(w,{2026,10,7},10,true).forecast);w.details=Json::object();auto noCode=weatherNow(w,{2026,10,7},10,false);assert(noCode.valid&&!noCode.hasCode);Weather empty;assert(!weatherNow(empty,{2026,10,8},0,false).valid);assert(freshObservation(1000,1200,true));assert(!freshObservation(1000,1200,false));assert(!freshObservation(1000,4000,true));assert(!freshObservation(2000,1000,true));assert(!freshObservation(0,1000,true));std::cout<<"Offline hourly/day rollover, midnight, timezone-local input, daily ranges, expired horizons, null data and fresh online observations: PASS\n";}
